import React, { createContext, useContext, useState, useCallback, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";

const PageTransitionContext = createContext(null);

export const PageTransitionProvider = ({ children }) => {
  const navigate = useNavigate();
  const location = useLocation();

  const [transitionState, setTransitionState] = useState({
    active: false,
    phase: "idle", // 'idle' | 'expanding' | 'fading'
    x: 0,
    y: 0,
  });

  const startTransition = useCallback(
    ({ x, y, targetUrl }) => {
      // Prevent double triggers
      if (transitionState.active) return;

      const clickX = typeof x === "number" && !isNaN(x) ? x : window.innerWidth / 2;
      const clickY = typeof y === "number" && !isNaN(y) ? y : window.innerHeight / 2;

      setTransitionState({
        active: true,
        phase: "expanding",
        x: clickX,
        y: clickY,
      });

      // Once the arrow has scaled up completely and engulfed the viewport (~550ms), navigate to the new page
      setTimeout(() => {
        navigate(targetUrl);
        window.scrollTo({ top: 0, behavior: "instant" });

        // Once the new page loads, smoothly fade out the white arrow cover to reveal the page
        setTimeout(() => {
          setTransitionState((prev) => ({ ...prev, phase: "fading" }));

          setTimeout(() => {
            setTransitionState({ active: false, phase: "idle", x: 0, y: 0 });
          }, 450);
        }, 100);
      }, 550);
    },
    [navigate, transitionState.active]
  );

  useEffect(() => {
    if (!transitionState.active) {
      window.scrollTo({ top: 0, behavior: "instant" });
    }
  }, [location.pathname, transitionState.active]);

  return (
    <PageTransitionContext.Provider value={{ startTransition, transitionState }}>
      {children}
      <ArrowScaleTransitionOverlay state={transitionState} />
    </PageTransitionContext.Provider>
  );
};

export const usePageTransition = () => {
  const ctx = useContext(PageTransitionContext);
  if (!ctx) {
    throw new Error("usePageTransition must be used within a PageTransitionProvider");
  }
  return ctx;
};

/**
 * Click-Spawned Arrow Scale Transition Overlay
 * - Spawns a genuine SVG <path> of a diagonal Top-Right Arrow (↗) EXACTLY at (x, y).
 * - Zero border-radius. Zero circles.
 * - Scales up massively from scale: 0 to scale: 500, engulfing the viewport with solid white.
 */
const ArrowScaleTransitionOverlay = ({ state }) => {
  const { active, phase, x, y } = state;

  return (
    <AnimatePresence>
      {active && (
        <div
          className="fixed inset-0 pointer-events-none"
          style={{ zIndex: 999999, overflow: "hidden" }}
        >
          {/* Positioned directly at the click coordinates with transformOrigin at center */}
          <motion.div
            key="arrow-scale-overlay"
            className="fixed pointer-events-none"
            style={{
              left: x,
              top: y,
              width: 100,
              height: 100,
              marginLeft: -50,
              marginTop: -50,
              transformOrigin: "50% 50%",
              willChange: "transform, opacity",
            }}
            initial={{ scale: 0, opacity: 1 }}
            animate={
              phase === "expanding"
                ? { scale: 500, opacity: 1 }
                : { scale: 500, opacity: 0 }
            }
            transition={
              phase === "expanding"
                ? { duration: 0.65, ease: [0.76, 0, 0.24, 1] }
                : { duration: 0.45, ease: "easeOut" }
            }
          >
            {/* Genuine Top-Right Diagonal Arrow (↗) SVG Path */}
            <svg
              viewBox="0 0 100 100"
              width="100"
              height="100"
              style={{ overflow: "visible" }}
            >
              <path
                d="M 90 10 L 90 62 L 64 50 L 28 86 L 14 72 L 50 36 L 38 10 Z"
                fill="#ffffff"
              />
            </svg>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
};
